#include <bits/stdc++.h>
using namespace std;
const int MAXN = 10000, MAXM = MAXN * 100;
const long long INF = LLONG_MAX >> 5;
class MinCostMaxFlow {
private:
    int head[MAXN], to[MAXM], nxt[MAXM], cap[MAXM], ptr, sink;
    long long cost[MAXM], total;
    inline void add_raw(int u, int v, long long w, int c) {
        to[ptr] = v; cost[ptr] = w; cap[ptr] = c;
        nxt[ptr] = head[u]; head[u] = ptr++;
    }
    int dist[MAXN], cur[MAXN]; bool inq[MAXN];
    bool spfa(int s, int t) {
        memset(inq, 0, sizeof(inq));
        memset(dist, -1, sizeof(dist));
        queue<int> q; q.push(s);
        dist[s] = 0; inq[s] = 1;
        while (!q.empty()) {
            int u = q.front(); q.pop(); inq[u] = 0;
            for (int i = head[u]; i != -1; i = nxt[i]) {
                if (cost[i] && (dist[to[i]] == -1 || dist[to[i]] > dist[u] + cap[i])) {
                    dist[to[i]] = dist[u] + cap[i];
                    if (!inq[to[i]]) {
                        inq[to[i]] = 1;
                        q.push(to[i]);
                    }
                }
            }
        }
        return dist[t] != -1;
    }
    long long dfs(int u, long long flow) {
        if (u == sink) return flow;
        inq[u] = 1;
        long long pushed = flow;
        for (int i = (cur[u] != -1 ? cur[u] : head[u]); i != -1; i = nxt[i]) {
            if (!inq[to[i]] && cost[i] && dist[to[i]] == dist[u] + cap[i]) {
                cur[u] = i;
                long long f = dfs(to[i], min(flow, cost[i]));
                total += f * cap[i];
                cost[i] -= f; cost[i ^ 1] += f;
                flow -= f;
                if (!flow) break;
            }
        }
        return pushed - flow;
    }
public:
    MinCostMaxFlow() { memset(head, -1, sizeof(head)); memset(nxt, -1, sizeof(nxt)); }
    inline void add_edge(int u, int v, long long w, int c) {
        add_raw(u, v, w, c);
        add_raw(v, u, 0, -c);
    }
    long long dinic(int s, int t) {
        total = 0; sink = t;
        while (spfa(s, t)) {
            memset(cur, -1, sizeof(cur));
            dfs(s, INF);
        }
        return total;
    }
};
MinCostMaxFlow g;
int n, m, kk, c, d, a[55];
int main() {
    ios::sync_with_stdio(false);
    cin >> n >> m >> kk >> c >> d;
    for (int i = 1; i <= kk; ++i) cin >> a[i];
    int s = 0, t = n * 100 + 1;
    // Precompute val for each j
    int val[55];
    for (int j = 1; j <= kk; ++j) val[j] = c + d * (j * j - (j - 1) * (j - 1));
    for (int i = 1; i <= 100; ++i) g.add_edge(i, t, INF, 0);
    for (int i = 1; i <= kk; ++i) g.add_edge(s, (a[i] - 1) * 100 + 1, 1, 0);
    for (int i = 2; i <= n; ++i)
        for (int j = 1; j < 100; ++j)
            g.add_edge((i - 1) * 100 + j, (i - 1) * 100 + j + 1, INF, c);
    int t1, t2;
    for (int _ = 1; _ <= m; ++_) {
        cin >> t1 >> t2;
        for (int i = 1; i < 100; ++i)
            for (int j = 1; j <= kk; ++j) {
                g.add_edge((t1 - 1) * 100 + i, (t2 - 1) * 100 + i + 1, 1, val[j]);
                g.add_edge((t2 - 1) * 100 + i, (t1 - 1) * 100 + i + 1, 1, val[j]);
            }
    }
    cout << g.dinic(s, t) << endl;
    return 0;
}
